'use client';

import { useId, useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll, type WordRollWord } from '@/components/core/word-roll';
import {
  type AutoplayStep,
  useAutoplay,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import {
  keyDelayOf,
  PRESS_LEAD_MS,
  spokenUnless,
  usePress,
} from '@/registry/ndeko/lib/demonstration';
import { countOf } from '@/registry/ndeko/lib/words';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { type Segment, Segments } from '@/registry/ndeko/ui/segments';

import {
  type BillingPeriod,
  HOUR_RANGE,
  type Plan,
  SEAT_RANGE,
  SECTION,
  START,
} from './data';
import { EstimateCard } from './estimate-card';
import { MeterSlider } from './meter-slider';
import { PlanColumns } from './plan-columns';
import {
  type CapNotice,
  capNoticeOf,
  estimateOf,
  fittingPlanOf,
  formatMoney,
  hourTicksOf,
  MONEY_FORMAT,
  PERIOD_ORDER,
  seatTicksOf,
  type Usage,
  yearlySavingOf,
} from './pricing-model';

const PERIODS: Segment<BillingPeriod>[] = [
  { value: 'monthly', label: 'Monthly' },
  { value: 'yearly', label: 'Yearly' },
];

/** Where the demonstration takes the two numbers: past the cap of Starter, then past the hours it includes. */
const DEMO = {
  seats: 14,
  hoursPerPerson: 30,
};

/** The pause between two notches of a slider the demonstration drags. */
const DRAG_STEP_MS = 110;

const LOOP_AFTER_MS = 3200;

/** A drag of the demonstration, one notch after the other, through the same handler a hand uses. */
function dragSteps(
  from: number,
  to: number,
  write: (value: number) => void,
  startAfter: number
): AutoplayStep[] {
  const distance = to - from;
  const direction = Math.sign(distance);
  const count = Math.abs(distance);
  const indexes = Array.from({ length: count }, (_, index) => index);
  return indexes.map((index) => {
    const walked = index + 1;
    const offset = walked * direction;
    const value = from + offset;
    const after = keyDelayOf(index, startAfter, DRAG_STEP_MS);
    return { after, run: () => write(value) };
  });
}

/** The amount keeps its place while its digits roll; only a change of period rolls the words around it. */
function savingWordsOf(period: BillingPeriod, saving: number): WordRollWord[] {
  const amount: WordRollWord = {
    key: 'saving',
    text: formatMoney(saving),
    node: (
      <MotionNumber
        value={saving}
        format={MONEY_FORMAT}
        className='text-foreground font-medium'
      />
    ),
  };
  if (period === 'yearly') {
    return ['Saving', amount, 'a', 'year'];
  }
  return ['Yearly', 'billing', 'saves', amount];
}

function announcementOf(fit: Plan, notice: CapNotice | null) {
  if (notice) {
    return `${fit.name} fits. ${notice.plan.name} holds up to ${notice.seats} seats.`;
  }
  return `${fit.name} fits your numbers.`;
}

export default function Pricing03() {
  const [seats, setSeats] = useState(START.seats);
  const [hoursPerPerson, setHoursPerPerson] = useState(START.hoursPerPerson);
  const [period, setPeriod] = useState<BillingPeriod>(START.period);
  const { pressed, press } = usePress<'fix'>();
  const markerId = useId();
  const seatsId = useId();
  const hoursId = useId();
  const usage: Usage = { seats, hoursPerPerson, period };
  const fit = fittingPlanOf(usage);
  const estimate = estimateOf(fit, usage);
  const notice = capNoticeOf(usage, fit);
  const seatTicks = seatTicksOf(usage);
  const hourTicks = hourTicksOf(usage);
  const saving = yearlySavingOf(fit, seats);
  const savingWords = savingWordsOf(period, saving);
  const periodOrder = PERIOD_ORDER[period];

  function fixSeats() {
    if (!notice) {
      return;
    }
    setSeats(notice.seats);
  }

  function startOver() {
    setSeats(START.seats);
    setHoursPerPerson(START.hoursPerPerson);
    setPeriod(START.period);
  }

  function seatsTextOf(value: number) {
    const valueUsage: Usage = { ...usage, seats: value };
    const plan = fittingPlanOf(valueUsage);
    const label = countOf(value, 'seat');
    return `${label}, ${plan.name} fits`;
  }

  function hoursTextOf(value: number) {
    const valueUsage: Usage = { ...usage, hoursPerPerson: value };
    const plan = fittingPlanOf(valueUsage);
    const label = countOf(value, 'hour');
    return `${label} each, ${plan.name} fits`;
  }

  const steps: AutoplayStep[] = [
    ...dragSteps(START.seats, DEMO.seats, setSeats, 1400),
    { after: 1700, run: () => press('fix') },
    { after: PRESS_LEAD_MS, run: fixSeats },
    ...dragSteps(
      START.hoursPerPerson,
      DEMO.hoursPerPerson,
      setHoursPerPerson,
      1500
    ),
    { after: 1600, run: () => setPeriod('yearly') },
  ];
  const { ref, isAutoplaying } = useAutoplay(steps, {
    loopAfter: LOOP_AFTER_MS,
    onReset: startOver,
  });
  const announcement = announcementOf(fit, notice);
  const message = spokenUnless(isAutoplaying, announcement);

  useKeptHeight(ref);

  return (
    <section className='@container'>
      <div
        ref={ref}
        className='mx-auto flex min-h-[55rem] max-w-6xl flex-col gap-8 px-4 py-16 @2xl:gap-10 @2xl:px-6 @2xl:py-24'
      >
        <div className='flex flex-col gap-6 @4xl:flex-row @4xl:items-end @4xl:justify-between'>
          <div className='flex max-w-2xl flex-col gap-3'>
            <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
              {SECTION.title}
            </h2>
            <p className='text-muted-foreground text-base text-pretty'>
              {SECTION.description}
            </p>
          </div>
          <div className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <Segments
              value={period}
              segments={PERIODS}
              onValueChange={setPeriod}
              label='Billing period'
            />
            <p className='text-muted-foreground text-xs tabular-nums'>
              <WordRoll words={savingWords} value={periodOrder} />
            </p>
          </div>
        </div>
        <div className='grid items-start gap-6 @4xl:grid-cols-[minmax(0,1fr)_20rem]'>
          <div className='flex min-w-0 flex-col gap-4'>
            <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] grid gap-x-8 gap-y-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @md:p-5 @2xl:grid-cols-2'>
              <MeterSlider
                id={seatsId}
                label='People who record'
                unit='seats'
                range={SEAT_RANGE}
                value={seats}
                ticks={seatTicks}
                valueTextOf={seatsTextOf}
                onValueChange={setSeats}
              />
              <MeterSlider
                id={hoursId}
                label='Hours each one records a month'
                unit='hours'
                range={HOUR_RANGE}
                value={hoursPerPerson}
                ticks={hourTicks}
                valueTextOf={hoursTextOf}
                onValueChange={setHoursPerPerson}
              />
            </div>
            <PlanColumns period={period} fit={fit} markerId={markerId} />
          </div>
          <EstimateCard
            estimate={estimate}
            period={period}
            notice={notice}
            isFixPressed={pressed === 'fix'}
            onFix={fixSeats}
          />
        </div>
      </div>
      <LiveRegion message={message} />
    </section>
  );
}

'use client';

import { NumberField } from '@base-ui/react/number-field';
import { AnimatePresence, motion } from 'motion/react';
import type { CSSProperties } from 'react';

import { fadePresence } from '@/registry/ndeko/lib/motion-presets';
import { CONTROL_RECIPE } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Slider, SliderThumbValue } from '@/registry/ndeko/ui/slider';

import type { Range } from './data';
import { formatCount, type Tick } from './pricing-model';

/** Below this share of the track between two ticks their names would touch: the marks stay, the names go. */
const MIN_NAME_GAP = 0.16;

/** Two names written towards each other need the room of both. */
const MIN_FACING_GAP = 0.34;

/** A tick past this share of the track writes its name on its left, so the name never leaves the block. */
const NAME_ON_LEFT_FROM = 0.78;

const TICK_PRESENCE = fadePresence();

/** Seats and hours are whole: a typed 12.5 rounds to 13 instead of reaching the estimate. */
const WHOLE_NUMBERS: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };

function amountOf(value: number | readonly number[]) {
  if (typeof value === 'number') {
    return value;
  }
  return value[0];
}

function shareOf(value: number, range: Range) {
  const span = range.max - range.min;
  const offset = value - range.min;
  return offset / span;
}

/** The anchor has no width and moves by a share of the row, so it glides with a transform and never widens the page. */
function anchorStyleOf(share: number): CSSProperties {
  const percent = share * 100;
  return { transform: `translateX(${percent}cqw)` };
}

function isNameOnLeft(share: number) {
  return share >= NAME_ON_LEFT_FROM;
}

function nameSideOf(share: number) {
  if (isNameOnLeft(share)) {
    return 'end-1.5';
  }
  return 'start-1.5';
}

/** True when two neighbouring ticks have room for both names, wherever each name is written. */
function isClearBetween(
  first: Tick | undefined,
  second: Tick | undefined,
  range: Range
) {
  if (!first || !second) {
    return true;
  }
  const firstShare = shareOf(first.value, range);
  const secondShare = shareOf(second.value, range);
  const gap = secondShare - firstShare;
  const isFirstOnRight = !isNameOnLeft(firstShare);
  const isSecondOnLeft = isNameOnLeft(secondShare);
  const isFacing = isFirstOnRight && isSecondOnLeft;
  if (isFacing) {
    return gap >= MIN_FACING_GAP;
  }
  return gap >= MIN_NAME_GAP;
}

function hasRoomForName(ticks: readonly Tick[], index: number, range: Range) {
  const tick = ticks[index];
  const isClearBefore = isClearBetween(ticks[index - 1], tick, range);
  const isClearAfter = isClearBetween(tick, ticks[index + 1], range);
  return isClearBefore && isClearAfter;
}

type TickRowProps = {
  ticks: readonly Tick[];
  range: Range;
};

/** Marks under the track where the plan that fits changes, named with the plan they lead to. */
function TickRow({ ticks, range }: TickRowProps) {
  return (
    <div aria-hidden='true' className='@container relative -mt-1 h-6'>
      <AnimatePresence initial={false}>
        {ticks.map((tick, index) => {
          const share = shareOf(tick.value, range);
          const showsName = hasRoomForName(ticks, index, range);
          return (
            <span
              key={tick.key}
              style={anchorStyleOf(share)}
              className='absolute top-0 left-0 w-0 transition-transform duration-300 ease-(--ease-out-strong)'
            >
              <motion.span {...TICK_PRESENCE} className='absolute top-0 left-0'>
                <span className='bg-foreground/30 absolute top-0 left-0 h-2 w-px -translate-x-1/2' />
                {showsName && (
                  <span
                    className={cn(
                      'text-muted-foreground absolute top-2 text-xs whitespace-nowrap',
                      nameSideOf(share)
                    )}
                  >
                    {tick.plan.name}
                  </span>
                )}
              </motion.span>
            </span>
          );
        })}
      </AnimatePresence>
    </div>
  );
}

type MeterSliderProps = {
  /** The id of the typed field, so its label names it. */
  id: string;
  label: string;
  /** What the typed number counts, written after the field. */
  unit: string;
  range: Range;
  value: number;
  ticks: readonly Tick[];
  /** What the thumb says to a screen reader, for example "14 seats, Team fits". */
  valueTextOf: (value: number) => string;
  onValueChange: (value: number) => void;
};

/** One number set three ways: dragged or keyed on the slider, or typed in the field beside its label. */
export function MeterSlider({
  id,
  label,
  unit,
  range,
  value,
  ticks,
  valueTextOf,
  onValueChange,
}: MeterSliderProps) {
  const bubble = formatCount(value);

  function changeFromSlider(next: number | readonly number[]) {
    const amount = amountOf(next);
    onValueChange(amount);
  }

  function changeFromField(next: number | null) {
    if (next === null) {
      return;
    }
    onValueChange(next);
  }

  function spokenValueOf(_formatted: string, next: number) {
    return valueTextOf(next);
  }

  return (
    <div className='flex flex-col gap-1.5'>
      <div className='flex items-center justify-between gap-3'>
        <label htmlFor={id} className='text-[13px] font-medium text-pretty'>
          {label}
        </label>
        <NumberField.Root
          id={id}
          value={value}
          min={range.min}
          max={range.max}
          step={range.step}
          locale='en-US'
          format={WHOLE_NUMBERS}
          onValueChange={changeFromField}
          className='flex shrink-0 items-center gap-2'
        >
          <NumberField.Input
            className={cn(
              CONTROL_RECIPE,
              'h-8 w-16 px-2.5 text-end tabular-nums'
            )}
          />
          <span className='text-muted-foreground w-10 text-xs'>{unit}</span>
        </NumberField.Root>
      </div>
      <Slider
        value={value}
        min={range.min}
        max={range.max}
        step={range.step}
        thumbLabels={[label]}
        getAriaValueText={spokenValueOf}
        thumbContent={() => <SliderThumbValue>{bubble}</SliderThumbValue>}
        onValueChange={changeFromSlider}
      />
      <TickRow ticks={ticks} range={range} />
    </div>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { INSTANT } from '@/registry/ndeko/lib/motion-presets';
import { Wash } from '@/registry/ndeko/ui/wash';

import { type BillingPeriod, type Plan, PLANS } from './data';
import { formatRate, MONEY_FORMAT, seatPriceOf } from './pricing-model';

const GLIDE: Transition = { type: 'spring', bounce: 0, duration: 0.45 };

function glideOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return GLIDE;
}

function currentOf(isFit: boolean) {
  if (isFit) {
    return 'true' as const;
  }
  return undefined;
}

type PlanColumnProps = {
  plan: Plan;
  period: BillingPeriod;
  fit: Plan;
  markerId: string;
  glide: Transition;
};

function PlanColumn({ plan, period, fit, markerId, glide }: PlanColumnProps) {
  const isFit = plan === fit;
  const seatPrice = seatPriceOf(plan, period);
  const extraHourPrice = formatRate(plan.pricePerExtraHour);

  return (
    <li
      aria-current={currentOf(isFit)}
      className='bg-foreground/[0.03] dark:bg-foreground/[0.04] relative isolate flex flex-col gap-3 rounded-xl p-4'
    >
      {isFit && (
        <motion.span
          layoutId={markerId}
          layoutDependency={fit.id}
          transition={glide}
          aria-hidden='true'
          className='surface-brand absolute inset-0 -z-10 rounded-xl'
        >
          <Wash />
          <span className='text-primary-ink absolute end-4 top-4 text-xs font-medium'>
            Fits
          </span>
        </motion.span>
      )}
      <h3 className='text-sm font-medium'>
        {plan.name}
        {isFit && <span className='sr-only'>, fits your numbers</span>}
      </h3>
      <p className='flex items-baseline gap-1.5'>
        <MotionNumber
          value={seatPrice}
          format={MONEY_FORMAT}
          className='text-2xl font-semibold'
        />
        <span className='text-muted-foreground text-xs'>per seat a month</span>
      </p>
      <ul className='text-muted-foreground flex flex-col gap-1 text-xs tabular-nums'>
        <li>{plan.includedHoursPerSeat} hours included per seat</li>
        <li>{extraHourPrice} per extra hour</li>
        <li>Up to {plan.maxSeats} seats</li>
      </ul>
    </li>
  );
}

type PlanColumnsProps = {
  period: BillingPeriod;
  fit: Plan;
  /** Unique to this block on the page, so two calculators never share a marker. */
  markerId: string;
};

/** The plans side by side, with one lifted marker that glides to the plan that fits. */
export function PlanColumns({ period, fit, markerId }: PlanColumnsProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const glide = glideOf(shouldReduceMotion);

  return (
    <ul aria-label='Plans' className='grid gap-2 @xl:grid-cols-3'>
      {PLANS.map((plan) => (
        <PlanColumn
          key={plan.id}
          plan={plan}
          period={period}
          fit={fit}
          markerId={markerId}
          glide={glide}
        />
      ))}
    </ul>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { type ReactNode, useRef } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll, type WordRollWord } from '@/components/core/word-roll';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { InfoIcon } from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';

import { type BillingPeriod, SECTION } from './data';
import {
  type CapNotice,
  type Estimate,
  formatMoney,
  formatRate,
  MONEY_FORMAT,
  PERIOD_ORDER,
  yearlySeatBillOf,
} from './pricing-model';

/** The amount keeps its place while its digits roll; only a change of period rolls the words around it. */
function billingWordsOf(
  period: BillingPeriod,
  estimate: Estimate
): WordRollWord[] {
  if (period === 'monthly') {
    return ['Billed', 'every', 'month'];
  }
  const yearlyBill = yearlySeatBillOf(estimate);
  const amount: WordRollWord = {
    key: 'yearly-bill',
    text: formatMoney(yearlyBill),
    node: <MotionNumber value={yearlyBill} format={MONEY_FORMAT} />,
  };
  return ['Seats', 'billed', amount, 'once', 'a', 'year'];
}

type LineProps = {
  term: string;
  detail: ReactNode;
  children: ReactNode;
};

function Line({ term, detail, children }: LineProps) {
  return (
    <div className='flex items-start justify-between gap-3'>
      <dt className='flex min-w-0 flex-col gap-0.5'>
        <span>{term}</span>
        <span className='text-muted-foreground text-xs tabular-nums'>
          {detail}
        </span>
      </dt>
      <dd className='font-medium tabular-nums'>{children}</dd>
    </div>
  );
}

type NoticeProps = {
  notice: CapNotice;
  isFixPressed: boolean;
  onFix: () => void;
};

function Notice({ notice, isFixPressed, onFix }: NoticeProps) {
  const total = formatMoney(notice.total);

  return (
    <div className='pt-4'>
      <div className='bg-info/10 flex flex-col gap-2.5 rounded-lg p-3'>
        <p className='flex gap-2 text-[13px] text-pretty'>
          <InfoIcon className='text-info-foreground mt-0.5 size-4 shrink-0' />
          <span>
            {notice.plan.name} holds up to {notice.seats} seats. With{' '}
            {notice.seats} seats there, your month comes to {total}.
          </span>
        </p>
        <Button
          type='button'
          variant='outline'
          size='sm'
          onClick={onFix}
          className={cn('ms-6 self-start', pressedQuietOf(isFixPressed))}
        >
          Use {notice.seats} seats on {notice.plan.name}
        </Button>
      </div>
    </div>
  );
}

type EstimateCardProps = {
  estimate: Estimate;
  period: BillingPeriod;
  notice: CapNotice | null;
  isFixPressed: boolean;
  onFix: () => void;
};

/** The month on the plan that fits, line by line, with the seat-cap notice and its fix. */
export function EstimateCard({
  estimate,
  period,
  notice,
  isFixPressed,
  onFix,
}: EstimateCardProps) {
  const startRef = useRef<HTMLAnchorElement>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);
  const planName = estimate.plan.name;
  const extraHourPrice = formatRate(estimate.plan.pricePerExtraHour);
  const billingWords = billingWordsOf(period, estimate);
  const periodOrder = PERIOD_ORDER[period];

  /** The fix folds the notice away with the button that was pressed: the focus goes on to the next action. */
  function fixByHand() {
    onFix();
    startRef.current?.focus();
  }

  return (
    <section
      aria-label='Your estimate'
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex flex-col rounded-xl p-5 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      <div className='flex items-center justify-between gap-3'>
        <h3 className='min-w-0 text-sm font-medium'>
          <WordRoll text={`Your month on ${planName}`} />
        </h3>
        <Badge variant='secondary'>Illustrative</Badge>
      </div>
      <dl className='mt-4 flex flex-col gap-3 text-[13px]'>
        <Line
          term='Seats'
          detail={
            <>
              <MotionNumber value={estimate.seats} /> ×{' '}
              <MotionNumber value={estimate.seatPrice} format={MONEY_FORMAT} />
            </>
          }
        >
          <MotionNumber value={estimate.seatCost} format={MONEY_FORMAT} />
        </Line>
        <Line
          term='Hours recorded'
          detail={
            <>
              <MotionNumber value={estimate.includedHours} /> included with the
              seats
            </>
          }
        >
          <MotionNumber value={estimate.recordedHours} suffix=' h' />
        </Line>
        <Line
          term='Extra hours'
          detail={
            <>
              <MotionNumber value={estimate.extraHours} /> × {extraHourPrice}
            </>
          }
        >
          <MotionNumber value={estimate.extraCost} format={MONEY_FORMAT} />
        </Line>
      </dl>
      <div className='bg-foreground/[0.04] mt-4 flex flex-col gap-1 rounded-lg p-3'>
        <div className='flex items-baseline justify-between gap-3'>
          <span className='text-[13px]'>Total per month</span>
          <MotionNumber
            value={estimate.total}
            format={MONEY_FORMAT}
            className='text-[1.75rem] leading-none font-semibold'
          />
        </div>
        <p className='text-muted-foreground text-xs tabular-nums'>
          <WordRoll words={billingWords} value={periodOrder} />
        </p>
      </div>
      <AnimatePresence initial={false}>
        {notice && (
          <motion.div key='notice' {...presence} className='overflow-hidden'>
            <Notice
              notice={notice}
              isFixPressed={isFixPressed}
              onFix={fixByHand}
            />
          </motion.div>
        )}
      </AnimatePresence>
      <Button
        size='lg'
        nativeButton={false}
        render={<a href='#' ref={startRef} />}
        className='mt-5 w-full'
      >
        <WordRoll text={`Start with ${planName}`} />
      </Button>
      <p className='text-muted-foreground mt-3 text-xs text-pretty'>
        {SECTION.footnote}
      </p>
    </section>
  );
}

import {
  type BillingPeriod,
  HOUR_RANGE,
  type Plan,
  PLANS,
  type Range,
  SEAT_RANGE,
} from './data';

export type Usage = {
  seats: number;
  hoursPerPerson: number;
  period: BillingPeriod;
};

export type Estimate = {
  plan: Plan;
  seats: number;
  seatPrice: number;
  seatCost: number;
  recordedHours: number;
  includedHours: number;
  extraHours: number;
  extraCost: number;
  total: number;
};

/** A place on a slider where the plan that fits changes. */
export type Tick = {
  /** The plan it leads to, counted, so a tick glides when the other number moves instead of being born again. */
  key: string;
  value: number;
  plan: Plan;
};

export type CapNotice = {
  plan: Plan;
  seats: number;
  total: number;
};

const MONTHS_PER_YEAR = 12;

/** The seat range ends at its cap, so this plan only answers for a number no slider can reach. */
const LARGEST_PLAN: Plan = PLANS.at(-1) ?? PLANS[0];

/** Monthly comes first, so a phrase that changes with the period rolls up to yearly and down back. */
export const PERIOD_ORDER: Record<BillingPeriod, number> = {
  monthly: 0,
  yearly: 1,
};

export const MONEY_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
};

const RATE_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
};

const MONEY_FORMATTER = new Intl.NumberFormat('en-US', MONEY_FORMAT);

const RATE_FORMATTER = new Intl.NumberFormat('en-US', RATE_FORMAT);

const COUNT_FORMATTER = new Intl.NumberFormat('en-US');

export function formatMoney(amount: number) {
  return MONEY_FORMATTER.format(amount);
}

export function formatRate(amount: number) {
  return RATE_FORMATTER.format(amount);
}

export function formatCount(count: number) {
  return COUNT_FORMATTER.format(count);
}

export function seatPriceOf(plan: Plan, period: BillingPeriod) {
  if (period === 'yearly') {
    return plan.yearlySeatPrice;
  }
  return plan.monthlySeatPrice;
}

/** Extra hours are rounded to whole dollars once, so the lines of an estimate always add up to its total. */
export function estimateOf(plan: Plan, usage: Usage): Estimate {
  const seatPrice = seatPriceOf(plan, usage.period);
  const seatCost = seatPrice * usage.seats;
  const recordedHours = usage.seats * usage.hoursPerPerson;
  const includedHours = usage.seats * plan.includedHoursPerSeat;
  const hoursOver = recordedHours - includedHours;
  const extraHours = Math.max(0, hoursOver);
  const exactExtraCost = extraHours * plan.pricePerExtraHour;
  const extraCost = Math.round(exactExtraCost);
  const total = seatCost + extraCost;
  return {
    plan,
    seats: usage.seats,
    seatPrice,
    seatCost,
    recordedHours,
    includedHours,
    extraHours,
    extraCost,
    total,
  };
}

function holdsSeats(plan: Plan, seats: number) {
  return seats <= plan.maxSeats;
}

function cheaperOf(current: Estimate | null, candidate: Estimate) {
  if (current === null) {
    return candidate;
  }
  if (candidate.total < current.total) {
    return candidate;
  }
  return current;
}

/** The cheapest plan that holds every seat. A tie goes to the smaller plan. */
export function fittingPlanOf(usage: Usage) {
  let best: Estimate | null = null;
  for (const plan of PLANS) {
    if (!holdsSeats(plan, usage.seats)) {
      continue;
    }
    const estimate = estimateOf(plan, usage);
    best = cheaperOf(best, estimate);
  }
  if (best === null) {
    return LARGEST_PLAN;
  }
  return best.plan;
}

/**
 * The plan one step down would cost less for these numbers but holds fewer seats than the team
 * has: the notice offers to stay on it with as many seats as it holds.
 */
export function capNoticeOf(usage: Usage, fit: Plan): CapNotice | null {
  const fitIndex = PLANS.indexOf(fit);
  const smaller: Plan | undefined = PLANS[fitIndex - 1];
  if (smaller === undefined) {
    return null;
  }
  if (holdsSeats(smaller, usage.seats)) {
    return null;
  }
  const smallerTotal = estimateOf(smaller, usage).total;
  const fitTotal = estimateOf(fit, usage).total;
  if (smallerTotal >= fitTotal) {
    return null;
  }
  const seats = smaller.maxSeats;
  const cappedUsage: Usage = { ...usage, seats };
  const total = estimateOf(smaller, cappedUsage).total;
  return { plan: smaller, seats, total };
}

function valuesOf(range: Range) {
  const values: number[] = [];
  for (let value = range.min; value <= range.max; value += range.step) {
    values.push(value);
  }
  return values;
}

const SEAT_VALUES = valuesOf(SEAT_RANGE);

const HOUR_VALUES = valuesOf(HOUR_RANGE);

function keyOfTick(ticks: Tick[], plan: Plan) {
  const earlier = ticks.filter((tick) => tick.plan === plan);
  return `${plan.id}-${earlier.length}`;
}

function ticksAlong(
  values: readonly number[],
  usageAt: (value: number) => Usage
) {
  const ticks: Tick[] = [];
  let previous: Plan | null = null;
  for (const value of values) {
    const usage = usageAt(value);
    const plan = fittingPlanOf(usage);
    const hasPrevious = previous !== null;
    const isChange = hasPrevious && plan !== previous;
    if (isChange) {
      const key = keyOfTick(ticks, plan);
      ticks.push({ key, value, plan });
    }
    previous = plan;
  }
  return ticks;
}

export function seatTicksOf(usage: Usage) {
  return ticksAlong(SEAT_VALUES, (seats) => ({ ...usage, seats }));
}

export function hourTicksOf(usage: Usage) {
  return ticksAlong(HOUR_VALUES, (hoursPerPerson) => ({
    ...usage,
    hoursPerPerson,
  }));
}

/** What yearly billing takes off the seats over twelve months. Extra hours are billed as they come. */
export function yearlySavingOf(plan: Plan, seats: number) {
  const perSeat = plan.monthlySeatPrice - plan.yearlySeatPrice;
  const perMonth = perSeat * seats;
  return perMonth * MONTHS_PER_YEAR;
}

export function yearlySeatBillOf(estimate: Estimate) {
  return estimate.seatCost * MONTHS_PER_YEAR;
}

export type BillingPeriod = 'monthly' | 'yearly';

export type PlanId = 'starter' | 'team' | 'scale';

